#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

// global ticket count
int gtickets = 0;

struct node_t {
    int            tickets;
    struct node_t *next;
};

struct node_t *head = NULL;

void insert(int tickets) {
    struct node_t *tmp = malloc(sizeof(struct node_t));
    assert(tmp != NULL);
    tmp->tickets = tickets;
    tmp->next    = head;
    head         = tmp;
    gtickets    += tickets;
}

void print_list() {
    struct node_t *curr = head;
    printf("List: ");
    while (curr) {
	printf("[%d] ", curr->tickets);
	curr = curr->next;
    }
    printf("\n");
}

int
main(int argc, char *argv[])
{
    if (argc != 3) {
	fprintf(stderr, "usage: lottery <seed> <loops>\n");
	exit(1);
    }
    int seed  = atoi(argv[1]);
    int loops = atoi(argv[2]);
    srandom(seed);

    // populate list with some number of jobs, each
    // with some number of tickets
    insert(50);
    insert(100);
    insert(25);

    print_list();

    int i;
    for (i = 0; i < loops; i++) {
	int counter            = 0;
	int winner             = random() % gtickets; // get winner
	struct node_t *current = head;

	// loop until the sum of ticket values is > the winner
	while (current) {
	    counter = counter + current->tickets;
	    if (counter > winner)
		break; // found the winner
	    current = current->next;
	}
	// current is the winner: schedule it...
	print_list();
	printf("winner: %d %d\n\n", winner, current->tickets);

    }
    return 0;
}

/*
 * scheduler.c
 * CSC139 – CPU Scheduling Project
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h> // getopt
#include <ctype.h>

// -----------------------------
// Data structures
// -----------------------------

typedef struct
{
    int id;             // job id
    double length;      // total runtime
    double remain;      // remaining runtime (for RR)
    double response;    // time of first run
    double turnaround;  // completion time
    double wait;        // accumulated waiting time
    double last_finish; // last time job left CPU
    int started;        // flag for first run
} Job;

// -----------------------------
// Globals (set by arguments)
// -----------------------------
char policy[10] = "FIFO"; // default
int nJobs = 3;
double *jobLengths = NULL; // parsed -l values
int hasJlist = 0;
int maxlen = 10;
int seed = 0;
int quantum = 1;
int solve = 0;

// -----------------------------
// Helper functions
// -----------------------------

// Split comma-separated job lengths
double *parseJobList(char *s, int *count)
{
    int len = strlen(s);
    int commas = 0;
    for (int i = 0; i < len; i++)
        if (s[i] == ',')
            commas++;
    int n = commas + 1;
    double *arr = (double *)malloc(sizeof(double) * n);

    char *token = strtok(s, ",");
    int idx = 0;
    while (token)
    {
        arr[idx++] = atof(token);
        token = strtok(NULL, ",");
    }
    *count = n;
    return arr;
}

// Comparator for qsort (SJF)
int cmpLen(const void *a, const void *b)
{
    double la = ((Job *)a)->length;
    double lb = ((Job *)b)->length;
    if (la < lb)
        return -1;
    if (la > lb)
        return 1;
    return 0;
}

// Print final statistics
void printStats(Job *jobs, int n)
{
    double respSum = 0, turnSum = 0, waitSum = 0;
    for (int i = 0; i < n; i++)
    {
        printf("  Job %3d -- Response: %3.2f  Turnaround %3.2f  Wait %3.2f\n",
               jobs[i].id, jobs[i].response, jobs[i].turnaround, jobs[i].wait);
        respSum += jobs[i].response;
        turnSum += jobs[i].turnaround;
        waitSum += jobs[i].wait;
    }
    printf("\n  Average -- Response: %3.2f  Turnaround %3.2f  Wait %3.2f\n\n",
           respSum / n, turnSum / n, waitSum / n);
}

// -----------------------------
// Scheduling policies
// -----------------------------

// FIFO (and SJF, since SJF is sorted FIFO)
void runFIFO(Job *jobs, int n)
{
    double t = 0.0;
    printf("Execution trace:\n");
    for (int i = 0; i < n; i++)
    {
        printf("  [ time %3.0f ] Run job %d for %.2f secs ( DONE at %.2f )\n",
               t, jobs[i].id, jobs[i].length, t + jobs[i].length);
        jobs[i].response = t;
        jobs[i].wait = t;
        jobs[i].turnaround = t + jobs[i].length;
        t += jobs[i].length;
    }
    printf("\nFinal statistics:\n");
    printStats(jobs, n);
}

// Round Robin
void runRR(Job *jobs, int n, int q)
{
    double t = 0.0;
    int done = 0;
    printf("Execution trace:\n");

    // initialize
    for (int i = 0; i < n; i++)
    {
        jobs[i].remain = jobs[i].length;
        jobs[i].response = -1;
        jobs[i].wait = 0;
        jobs[i].turnaround = 0;
        jobs[i].last_finish = 0;
        jobs[i].started = 0;
    }

    // use circular queue index
    while (done < n)
    {
        for (int i = 0; i < n; i++)
        {
            if (jobs[i].remain > 0)
            {
                // record first response
                if (!jobs[i].started)
                {
                    jobs[i].response = t;
                    jobs[i].started = 1;
                }
                // accumulate waiting
                jobs[i].wait += (t - jobs[i].last_finish);

                if (jobs[i].remain > q)
                {
                    printf("  [ time %3.0f ] Run job %3d for %.2f secs\n",
                           t, jobs[i].id, (double)q);
                    jobs[i].remain -= q;
                    t += q;
                    jobs[i].last_finish = t;
                }
                else
                {
                    printf("  [ time %3.0f ] Run job %3d for %.2f secs ...( DONE at %.2f )\n",
                           t, jobs[i].id, jobs[i].remain, t + jobs[i].remain);
                    t += jobs[i].remain;
                    jobs[i].remain = 0;
                    jobs[i].turnaround = t;
                    jobs[i].last_finish = t;
                    done++;
                }
            }
        }
    }
    printf("\nFinal statistics:\n");
    printStats(jobs, n);
}

// -----------------------------
// Main
// -----------------------------

int main(int argc, char *argv[])
{
    int opt;
    while ((opt = getopt(argc, argv, "s:j:l:m:p:q:c")) != -1)
    {
        switch (opt)
        {
        case 's':
            seed = atoi(optarg);
            break;
        case 'j':
            nJobs = atoi(optarg);
            break;
        case 'l':
            jobLengths = parseJobList(optarg, &nJobs);
            hasJlist = 1;
            break;
        case 'm':
            maxlen = atoi(optarg);
            break;
        case 'p':
            strncpy(policy, optarg, 9);
            break;
        case 'q':
            quantum = atoi(optarg);
            break;
        case 'c':
            solve = 1;
            break;
        default:
            fprintf(stderr, "Usage: %s -p POLICY -j jobs -l list -m maxlen -q quantum -s seed -c\n", argv[0]);
            exit(1);
        }
    }

    srand(seed);

    // Build job list
    Job *jobs = (Job *)malloc(sizeof(Job) * nJobs);
    if (hasJlist)
    {
        for (int i = 0; i < nJobs; i++)
        {
            jobs[i].id = i;
            jobs[i].length = jobLengths[i];
        }
    }
    else
    {
        for (int i = 0; i < nJobs; i++)
        {
            jobs[i].id = i;
            jobs[i].length = (rand() % maxlen) + 1;
        }
    }

    // Print args like Python
    printf("ARG policy %s\n", policy);
    if (!hasJlist)
    {
        printf("ARG jobs %d\n", nJobs);
        printf("ARG maxlen %d\n", maxlen);
        printf("ARG seed %d\n", seed);
    }
    else
    {
        printf("ARG jlist ");
        for (int i = 0; i < nJobs; i++)
        {
            printf("%g", jobs[i].length);
            if (i < nJobs - 1)
                printf(",");
        }
        printf("\n");
    }
    printf("\nHere is the job list, with the run time of each job:\n");
    for (int i = 0; i < nJobs; i++)
    {
        printf("  Job %d ( length = %.1f )\n", jobs[i].id, jobs[i].length);
    }
    printf("\n");

    if (!solve)
    {
        printf("Compute the turnaround time, response time, and wait time for each job.\n");
        printf("When you are done, re-run with -c to check the answers.\n");
        exit(0);
    }

    printf("** Solutions **\n\n");

    if (strcasecmp(policy, "SJF") == 0)
    {
        qsort(jobs, nJobs, sizeof(Job), cmpLen);
        runFIFO(jobs, nJobs);
    }
    else if (strcasecmp(policy, "FIFO") == 0)
    {
        runFIFO(jobs, nJobs);
    }
    else if (strcasecmp(policy, "RR") == 0)
    {
        runRR(jobs, nJobs, quantum);
    }
    else
    {
        fprintf(stderr, "Error: Policy %s not available\n", policy);
        exit(1);
    }

    free(jobs);
    if (jobLengths)
        free(jobLengths);
    return 0;
}

#ifndef GRADING_MODE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <unistd.h>
#include <sys/wait.h>

#define BLOCK_SIZE 1024
#define SYMBOLS 256
#define LARGE_PRIME 2147483647 // for modular hash
#define UMEM_SIZE (128 * 1024) // 128 KB managed heap for Step 2

/* Forward declarations for student functions*/
void *umalloc(size_t size);
void ufree(void *ptr);
unsigned long process_block(const unsigned char *buf, size_t len);
int run_single(const char *filename);
int run_multi(const char *filename);

/* =======================================================================
   PROVIDED CODE — DO NOT MODIFY
   -----------------------------------------------------------------------
   This section implements the complete Huffman tree construction logic
   and internal data structures.  It uses umalloc() and ufree() for all
   dynamic memory so that your allocator can be substituted later without
   touching this code.
   ======================================================================= */

/* ============================ STEP 2 ONLY ==============================
   The function and structures below will be used in Step 2 when you build
   your own memory allocator.  DO NOT USE OR MODIFY THIS CODE IN STEP 1.

   In Step 2, you will:
     - Use init_umem() to allocate a contiguous memory region.
     - Implement a FIRST-FIT allocator using the structures below.
     - Manage all memory inside this region manually.
   ======================================================================= */

void *init_umem(void)
{
    void *ptr = mmap(NULL, UMEM_SIZE,
                     PROT_READ | PROT_WRITE,
                     MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED)
    {
        perror("mmap");
        return NULL;
    }
    return ptr;
}

#define MAGIC 0xDEADBEEFLL // integrity check pattern

typedef struct
{
    long size;  // Size of the block (payload only)
    long magic; // Magic number for integrity check
} header_t;

typedef struct __node_t
{
    long size;             // Size of the free block
    struct __node_t *next; // Pointer to the next free block
} node_t;

/* =======================================================================
   Huffman and Heap Infrastructure (Given)
   ======================================================================= */

typedef struct Node
{
    unsigned char symbol;
    unsigned long freq;
    struct Node *left, *right;
} Node;

typedef struct
{
    Node **data;
    int size;
    int capacity;
} MinHeap;

MinHeap *heap_create(int capacity)
{
    MinHeap *h = umalloc(sizeof(MinHeap));
    h->data = umalloc(sizeof(Node *) * capacity);
    h->size = 0;
    h->capacity = capacity;
    return h;
}

void heap_swap(Node **a, Node **b)
{
    Node *tmp = *a;
    *a = *b;
    *b = tmp;
}

void heap_push(MinHeap *h, Node *node)
{
    int i = h->size++;
    h->data[i] = node;
    while (i > 0)
    {
        int p = (i - 1) / 2;
        if (h->data[p]->freq < h->data[i]->freq)
            break;
        heap_swap(&h->data[p], &h->data[i]);
        i = p;
    }
}

Node *heap_pop(MinHeap *h)
{
    if (h->size == 0)
        return NULL;
    Node *min = h->data[0];
    h->data[0] = h->data[--h->size];
    int i = 0;
    while (1)
    {
        int l = 2 * i + 1, r = l + 1, smallest = i;
        if (l < h->size && h->data[l]->freq < h->data[smallest]->freq)
            smallest = l;
        if (r < h->size && h->data[r]->freq < h->data[smallest]->freq)
            smallest = r;
        if (smallest == i)
            break;
        heap_swap(&h->data[i], &h->data[smallest]);
        i = smallest;
    }
    return min;
}

void heap_free(MinHeap *h)
{
    ufree(h->data);
    ufree(h);
}

Node *new_node(unsigned char sym, unsigned long freq, Node *l, Node *r)
{
    Node *n = umalloc(sizeof(Node));
    n->symbol = sym;
    n->freq = freq;
    n->left = l;
    n->right = r;
    return n;
}

void free_tree(Node *n)
{
    if (!n)
        return;
    free_tree(n->left);
    free_tree(n->right);
    ufree(n);
}

Node *build_tree(unsigned long freq[SYMBOLS])
{
    MinHeap *h = heap_create(SYMBOLS);
    for (int i = 0; i < SYMBOLS; i++)
        if (freq[i] > 0)
            heap_push(h, new_node((unsigned char)i, freq[i], NULL, NULL));
    if (h->size == 0)
    {
        heap_free(h);
        return NULL;
    }
    while (h->size > 1)
    {
        Node *a = heap_pop(h);
        Node *b = heap_pop(h);
        Node *p = new_node(0, a->freq + b->freq, a, b);
        heap_push(h, p);
    }
    Node *root = heap_pop(h);
    heap_free(h);
    return root;
}

unsigned long hash_tree(Node *n, unsigned long hash)
{
    if (!n)
        return hash;
    hash = (hash * 31 + n->freq + n->symbol) % LARGE_PRIME;
    hash = hash_tree(n->left, hash);
    hash = hash_tree(n->right, hash);
    return hash;
}

/* =======================================================================
   PROVIDED PRINTING UTILITIES (DO NOT MODIFY)
   -----------------------------------------------------------------------
   These helper functions standardize all program output for testing and
   grading. Students must call these rather than using printf() directly
   for block or final output.
   ======================================================================= */

void print_intermediate(int block_num, unsigned long hash, pid_t pid)
{
#ifdef DEBUG
#if DEBUG == 2
    printf("[PID %d] Block %d hash: %lu\n", pid, block_num, hash);
#elif DEBUG == 1
    printf("Block %d hash: %lu\n", block_num, hash);
#endif
#else
    (void)block_num;
    (void)hash;
    (void)pid;
#endif
}

void print_final(unsigned long final_hash)
{
    printf("Final signature: %lu\n", final_hash);
}

/* =======================================================================
   MAIN DISPATCH FUNCTION
   -----------------------------------------------------------------------
   Usage:
       ./hashproj <file>          -> run single-process version
       ./hashproj <file> -m       -> run multi-process version
   ======================================================================= */

int main(int argc, char *argv[])
{
    if (argc < 2)
    {
        fprintf(stderr, "Usage: %s <file> [-m]\n", argv[0]);
        return 1;
    }

    const char *filename = argv[1];
    int use_multi = (argc >= 3 && strcmp(argv[2], "-m") == 0);

    if (use_multi)
        return run_multi(filename);
    else
        return run_single(filename);
}

#endif // GRADING_MODE

/* =======================================================================
   STUDENT SECTION — IMPLEMENT THE FUNCTIONS BELOW
   -----------------------------------------------------------------------
   In Step 1 you will implement umalloc() and ufree() as simple wrappers
   around malloc() and free(). In Step 2, you will replace these with your
   own FIRST-FIT allocator that operates inside the region returned by
   init_umem().
   ======================================================================= */
#include <errno.h>

static void *umem_start = NULL;
static node_t *free_list = NULL;

void *umalloc(size_t size)
{
    //  return malloc(size);    step 1 version
    // Initialization
    if (!umem_start)
    {
        umem_start = init_umem();
        if (!umem_start)
        {
            perror("init_umem");
            return NULL;
        }
        free_list = (node_t *)umem_start;
        free_list->size = UMEM_SIZE - sizeof(node_t);
        free_list->next = NULL;
    }

    // Align to 8 bytes
    size = (size + 7) & ~7UL;
    size_t total = size + sizeof(header_t);

    node_t *prev = NULL;
    node_t *curr = free_list;

    while (curr)
    {
        if (curr->size >= (long)total)
        {
            char *alloc_start = (char *)curr;
            size_t remaining = curr->size - total;

            if (remaining > sizeof(node_t))
            {
                node_t *next_free = (node_t *)(alloc_start + total);
                next_free->size = remaining;
                next_free->next = curr->next;
                if (prev)
                    prev->next = next_free;
                else
                    free_list = next_free;
            }
            else
            {
                if (prev)
                    prev->next = curr->next;
                else
                    free_list = curr->next;
            }

            // Write
            header_t *hdr = (header_t *)alloc_start;
            hdr->size = size;
            hdr->magic = MAGIC;

            return (void *)(hdr + 1);
        }
        prev = curr;
        curr = curr->next;
    }
    return NULL;
}

void ufree(void *ptr)
{
    // free(ptr);   step 1 version
    if (!ptr)
        return;

    header_t *hdr = ((header_t *)ptr) - 1;

    if (hdr->magic != MAGIC)
    {
        fprintf(stderr, "Invalid free or corrupted block!\n");
        exit(1);
    }

    hdr->magic = 0; // mark as freed
    node_t *newfree = (node_t *)hdr;
    newfree->size = hdr->size + sizeof(header_t);

    // Insert into free list sorted by address
    node_t *prev = NULL;
    node_t *curr = free_list;

    while (curr && curr < newfree)
    {
        prev = curr;
        curr = curr->next;
    }

    newfree->next = curr;
    if (prev)
        prev->next = newfree;
    else
        free_list = newfree;

    // Coalesce with next
    if (curr && (char *)newfree + newfree->size == (char *)curr)
    {
        newfree->size += sizeof(node_t) + curr->size;
        newfree->next = curr->next;
    }

    // Coalesce with previous
    if (prev && (char *)prev + prev->size == (char *)newfree)
    {
        prev->size += sizeof(node_t) + newfree->size;
        prev->next = newfree->next;
    }
}

unsigned long process_block(const unsigned char *buf, size_t len)
{
    /* -------------------------------------------------------------------
       TODO: Implement the logic to process one block of input data.

       Each block is a sequence of bytes of length `len`. Your goal is to:
         1. Count how many times each symbol (0–255) appears in the block.
         2. Build a Huffman tree based on these frequencies.
         3. Compute a hash value of the resulting tree using hash_tree().
         4. Free the tree before returning.
    ------------------------------------------------------------------- */

    /* Step 1: Initialize frequency table for all 256 possible symbols.
       Each index corresponds to an unsigned char value (0–255). */
    unsigned long freq[SYMBOLS] = {0};

    /* Step 2: Count symbol frequencies in this block. */
    for (size_t i = 0; i < len; i++)
    {
        /* TODO: Increment frequency for symbol buf[i] */
        freq[buf[i]]++;
    }

    /* Step 3: Build Huffman tree using provided build_tree() function.
       Pass in the frequency array you just filled. */
    Node *root = build_tree(freq); /* TODO: call build_tree(freq) */

    /* Step 4: Compute hash of the tree using provided hash_tree().
       Start with an initial hash value of 0. */
    unsigned long h = hash_tree(root, 0); /* TODO: call hash_tree(root, 0) */

    /* Step 5: Free the Huffman tree to avoid memory leaks. */
    /* TODO: call free_tree(root) */
    free_tree(root);

    /* Step 6: Return the computed hash value for this block. */
    return h; /* Replace with your hash variable */
}

/* -------------------------------------------------------------------
   TODO: Implement run_single()

   The single-process version should:
     1. Open the specified input file in binary mode.
     2. Read it in chunks of BLOCK_SIZE bytes into a local buffer.
     3. For each block:
          - Call process_block() to compute its hash.
          - Print the result using print_intermediate(block_num, hash, getpid()).
          - Accumulate the hashes into a final signature using modular addition:
                final_hash = (final_hash + hash) % LARGE_PRIME;
     4. After processing all blocks:
          - Close the input file.
          - Print the final signature with print_final(final_hash).
     5. Handle any file errors (e.g., fopen failure).
------------------------------------------------------------------- */
int run_single(const char *filename)
{
    FILE *fp = fopen(filename, "rb");
    if (!fp)
    {
        perror("fopen");
        return 1;
    }

    unsigned char buf[BLOCK_SIZE];
    unsigned long final_hash = 0;
    int block_num = 0;

    // 2) Read file in 1KB chunks; process each chunk
    while (1)
    {
        size_t n = fread(buf, 1, BLOCK_SIZE, fp);
        if (n == 0)
        {
            if (ferror(fp))
            {
                fclose(fp);
                // Still print final to keep a consistent exit path, or exit nonzero:
                // return 1;
                print_final(final_hash);
                return 1;
            }
            break;
        }

        // Compute per-block hash
        unsigned long h = process_block(buf, n);

        // Print intermediate output (DEBUG controls visibility)
        print_intermediate(block_num, h, getpid());

        // Accumulate into final hash
        final_hash = (final_hash + h) % LARGE_PRIME;

        block_num++;
    }

    fclose(fp);
    print_final(final_hash);

    return 0;
}

/* -------------------------------------------------------------------
   TODO: Implement run_multi()

   The multi-process version should:
     1. Open the specified input file in binary mode.
     2. Read it in chunks of BLOCK_SIZE bytes into a local buffer.
     3. For each block:
          - Create a pipe for communication between parent and child.
          - Fork a new process.
          - In the child process:
                * Close the read end of the pipe.
                * Call process_block() on the buffer.
                * Write the resulting hash to the pipe.
                * Close the write end and exit.
          - In the parent process:
                * Close the write end of the pipe.
                * Read the hash value from the pipe.
                * Close the read end.
                * Print the result using print_intermediate(block_num, hash, pid).
                * Add the hash into the running total:
                      final_hash = (final_hash + hash) % LARGE_PRIME;
     4. After processing all blocks:
          - Wait for all child processes to finish using waitpid().
          - Close the input file.
          - Print the final signature with print_final(final_hash).
     5. Handle all errors (e.g., fopen, pipe, or fork failures) gracefully.
------------------------------------------------------------------- */

int run_multi(const char *filename)
{
    FILE *fp = fopen(filename, "rb");
    if (!fp)
    {
        perror("fopen");
        return 1;
    }

    unsigned char buf[BLOCK_SIZE];
    unsigned long final_hash = 0;
    int block_num = 0;

    size_t n;
    while ((n = fread(buf, 1, BLOCK_SIZE, fp)) > 0)
    {
        int pipefd[2];
        if (pipe(pipefd) == -1)
        {
            perror("pipe");
            fclose(fp);
            return 1;
        }

        pid_t pid = fork();
        if (pid < 0)
        {
            perror("fork");
            fclose(fp);
            return 1;
        }

        if (pid == 0)
        {
            // ----- CHILD -----
            close(pipefd[0]);
            unsigned long h = process_block(buf, n);
            write(pipefd[1], &h, sizeof(h));
            close(pipefd[1]);
            _exit(0);
        }
        else
        {
            // ----- PARENT -----
            close(pipefd[1]);
            unsigned long h = 0;
            read(pipefd[0], &h, sizeof(h));
            close(pipefd[0]);

            print_intermediate(block_num, h, pid);
            final_hash = (final_hash + h) % LARGE_PRIME;
            block_num++;
        }
    }

    // Wait for all children to finish
    while (waitpid(-1, NULL, 0) > 0)
        ;
    fclose(fp);
    print_final(final_hash);

    return 0;
}

/* `````````````````````````````````````````````````````````````````````
 * Multi-Process Huffman Tree Construction with Shared Memory Allocator
 *
 * This program demonstrates correct concurrent programming with processes
 * sharing a custom memory allocator. The key challenge: after fork(),
 * child processes inherit pointers but must coordinate access to shared
 * data structures.
 *
 * Architecture:
 *   - Parent reads file in 1KB chunks
 *   - Each chunk is processed by a separate child process
 *   - All processes share a single memory allocator (protected by semaphore)
 *   - Results are collected in order via pipes
 *
 * Performance Characteristics:
 *   This implementation is CORRECT but INEFFICIENT. The global semaphore
 *   protecting the allocator creates severe lock contention - with N
 *   parallel children, most time is spent waiting for the lock rather
 *   than doing useful work. This is intentional: students will optimize
 *   this in later assignments by using per-thread pools or lock-free
 *   data structures.
 *
 * Key Design Decisions Explained:
 *
 * 1. Why free_list_ptr is a pointer-to-pointer in shared memory:
 *    After fork(), each process gets a copy of global variables. If
 *    free_list were a regular pointer, each child would have a stale
 *    copy of its value (pointing to wherever the head was when that
 *    child forked). By storing the pointer itself in mmap'd memory,
 *    all processes see the same memory location and can observe each
 *    other's updates to where the list head points.
 *
 * 2. Why semaphore initialization is conditional:
 *    Single-process mode doesn't need synchronization overhead. The
 *    use_multiprocess flag avoids initializing (and acquiring) the
 *    semaphore when running sequentially, eliminating unnecessary cost.
 *
 * 3. Why buffers are allocated via umalloc():
 *    Passing stack buffer pointers to children is unsafe - the parent's
 *    stack could be modified while children are reading. By allocating
 *    in shared memory, each child gets a stable copy. This also exercises
 *    the allocator, making lock contention observable.
 *
 * 4. Why three-phase execution:
 *    To achieve true parallelism, we separate forking (Phase 1) from
 *    result collection (Phase 2) from cleanup (Phase 3). This allows
 *    all children to execute simultaneously, contending for the allocator,
 *    which exposes the performance bottleneck students will optimize.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <unistd.h>
#include <sys/wait.h>
#include <semaphore.h>
#include <pthread.h>   // NEW: for threads & mutex
#include <stdatomic.h> // if you want counters later (optional)

#define BLOCK_SIZE 1024
#define SYMBOLS 256
#define LARGE_PRIME 2147483647
#define UMEM_SIZE (2 * 1024 * 1024) // 2 MB: large enough for ~1000 concurrent blocks

void *umalloc(size_t size);
void ufree(void *ptr);
unsigned long process_block(const unsigned char *buf, size_t len);
int run_single(const char *filename);
int run_multi(const char *filename);
int run_threads(const char *filename); // NEW: multi-threaded version

